#!/usr/bin/env bash
# Cursor afterShellExecution hook (harness/cursor/tea-rags/scripts/after-shell-execution.sh,
# generated by scripts/gen-harness-cursor.ts; bd tea-rags-mcp-xkbkv): maps Cursor's
# {command, output} onto the Claude PostToolUse(Bash) shape and runs the Claude
# plugin's cleanup-worktree-clone.sh (shipped verbatim next to it), with the
# resolved tea-rags directory on PATH. Always prints {} and exits 0.
set -u
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
HOOK="$ROOT/harness/cursor/tea-rags/scripts/after-shell-execution.sh"
PASS=0; FAIL=0
note() { if [ "$1" = 0 ]; then PASS=$((PASS+1)); echo "ok   - $2"; else FAIL=$((FAIL+1)); echo "FAIL - $2"; fi; }

# Fake `tea-rags`: `worktree list --json` prints two clones, one whose path is gone;
# `worktree remove <n>` is recorded.
FAKEBIN="$(mktemp -d)"; CALLS="$(mktemp)"; SCRATCH="$(mktemp -d)"; LIVE="$(mktemp -d)"
cat > "$FAKEBIN/tea-rags" <<EOF
#!/usr/bin/env bash
if [ "\$1 \$2" = "worktree list" ]; then
  echo '[{"path":"$SCRATCH/gone","worktreeName":"gone"},{"path":"$LIVE","worktreeName":"live"}]'
elif [ "\$1 \$2" = "worktree remove" ]; then
  echo "remove \$3" >> "$CALLS"
fi
exit 0
EOF
chmod +x "$FAKEBIN/tea-rags"
NOCLI="$(mktemp -d)"; ln -s "$(command -v jq)" "$NOCLI/jq"
BASE_PATH="/usr/bin:/bin"

run() { # $1=json payload, [$2=PATH], [$3=TEA_RAGS_BIN]
  : > "$CALLS"
  OUT=$(printf '%s' "$1" | env -u TEA_RAGS_BIN HOME="$SCRATCH" ${3:+TEA_RAGS_BIN="$3"} PATH="${2:-$FAKEBIN:$NOCLI:$BASE_PATH}" bash "$HOOK" 2>/dev/null)
  CODE=$?
}
after() { jq -cn --arg c "$1" --arg o "$2" '{hook_event_name:"afterShellExecution",command:$c,output:$o,duration:12,sandbox:false}'; }
quiet() { [ "$CODE" = 0 ] && [ "$OUT" = '{}' ]; }

[ -f "$HOOK" ]
note $? "hook script is generated"
[ -f "$ROOT/harness/cursor/tea-rags/scripts/cleanup-worktree-clone.sh" ]
note $? "the Claude cleanup script ships next to it"

run "$(after 'git worktree remove .claude/worktrees/x' '')"
{ quiet && grep -qxF 'remove gone' "$CALLS" && ! grep -qF 'remove live' "$CALLS"; }; note $? "worktree remove sweeps only clones whose path is gone"

run "$(after 'git -C /repo branch -D worktree-x' 'Deleted branch worktree-x')"
{ quiet && grep -qxF 'remove gone' "$CALLS"; }; note $? "branch -D sweeps too"

run "$(after 'git worktree remove x' 'fatal: x is not a working tree')"
{ quiet && [ ! -s "$CALLS" ]; }; note $? "failed teardown output skips the sweep"

run "$(after 'npm test' 'ok')"
{ quiet && [ ! -s "$CALLS" ]; }; note $? "a non-teardown command skips the sweep"

run "$(after 'git worktree remove x' '')" "$NOCLI:$BASE_PATH" "$FAKEBIN/tea-rags"
{ quiet && grep -qxF 'remove gone' "$CALLS"; }; note $? "TEA_RAGS_BIN off PATH is put on PATH for the cleanup"

run "$(after 'git worktree remove x' '')" "$NOCLI:$BASE_PATH"
quiet; note $? "missing tea-rags CLI fails open"

run 'not json'
{ quiet && [ ! -s "$CALLS" ]; }; note $? "malformed hook input fails open"

rm -rf "$FAKEBIN" "$NOCLI" "$CALLS" "$SCRATCH" "$LIVE"
echo "# $PASS passed, $FAIL failed"
[ "$FAIL" = 0 ]
